test("request() multicall", async () => {
  const chain = getChain();
  const rpc = createRpc({
    chain,
    common: context.common,
  });

  const blockData = await simulateBlock();
  const { eventCallbacks, indexingFunctions } = getBlocksIndexingBuild({
    interval: 1,
